{
  "name": "SQLite CAN消息读取器",
  "name_en": "SQLite CAN Message Reader",
  "manufacturer": "",
  "description": "一个非物理的软件组件，用于从简单的 SQLite/SQL 数据库中读取已记录的 CAN 总线消息。它适合实验中的总线通信数据回放、离线分析与日志检查，不直接控制任何实际仪器。",
  "description_en": "A non-physical software component for reading recorded CAN bus messages from a simple SQLite/SQL database. It is used for experiment data replay, offline analysis, and log inspection, and does not directly control any physical instrument.",
  "actions": [
    {
      "action_name": "auto-read_all",
      "description": "读取数据库中的全部 CAN 消息。",
      "description_en": "Read all CAN messages from the database."
    },
    {
      "action_name": "auto-stop",
      "description": "关闭数据库连接。",
      "description_en": "Close the database connection."
    }
  ],
  "tag_hints": [
    "CAN bus logging",
    "SQLite message storage",
    "recorded message replay",
    "offline data analysis",
    "experiment log reader"
  ]
}

